script:
(function () {
  'use strict';
  // Business debt consolidation: existing business debts (term/equipment loans, lines of credit,
  // business cards, merchant cash advances) paid off with one new term loan.
  //   Loans, lines and cards: each month interest = balance x APR / 12 (rounded to the cent), then
  //   the entered payment, until the balance is cleared. The payoff amount is today's balance.
  //   Merchant cash advance (MCA): payback = advance x factor rate, collected in n equal debits
  //   (n = term months x 252/12 business days for daily, x 52/12 for weekly). Its APR is the
  //   periodic rate i solving  debit x (1 - (1 + i)^-n) / i = advance, times the debits per year.
  //   Monthly cost = payback / term; payoff = the payback still owed (payback x months left / term),
  //   i.e. no early-payoff discount.
  //   New loan: amount L = payoffs + costs, grossed up for a financed % fee: L = (D + C) / (1 - f).
  //   Payment = rL / (1 - (1 + r)^-n), rounded to the cent (L / n at 0%); the last payment clears
  //   the balance. APR with fees: monthly rate solving PV(payments) = L - fee - costs, x 12.
  //   DSCR = yearly net operating income / yearly debt service (consolidated debts + other debt).
  // Verified (scratchpad b7opt/tests/bdc.test.js):
  //   $20,000 at 10% for 5 years -> $424.94 a month (standard amortization table value);
  //   $10,000 at 10% for 36 months with a $500 fee -> payment $322.67, APR 13.56% (discounting
  //   the 36 payments at that rate returns $9,500);
  //   MCA $40,000 x 1.35 over 9 months: daily (189 debits of $285.71) APR 84.12%, weekly (39 debits)
  //   82.77% - both matched by an independent Newton solve in Python; default MCA $30,000 x 1.30
  //   over 10 months daily -> 65.72%, matched the same way;
  //   DSCR on the defaults: $180,000 / ($6,550 x 12 + $12,000) = 1.99x before, / ($2,086.27 x 12 +
  //   $12,000) = 4.86x after; a 0% new loan returns payment = loan / months and APR 0.00%.
  var MAX_MONTHS = 1200;
  var LOAN_ROWS = 4, MCA_ROWS = 2;
  var TYPE_NAMES = { term: 'Term loan', line: 'Line of credit', card: 'Business credit card', equip: 'Equipment loan', other: 'Other business debt' };
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function cents(x) { return Math.round(x * 100) / 100; }

  // Pays a fixed amount each month until the balance is gone; returns the monthly payments.
  function payDown(balance, apr, payment) {
    var r = apr / 12, bal = balance, interestTotal = 0, pays = [];
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var interest = cents(bal * r);
      bal += interest;
      var pay = Math.min(payment, bal);
      bal -= pay; interestTotal += interest; pays.push(pay);
      if (bal <= 0.005) return { paidOff: true, pays: pays, interest: interestTotal };
    }
    return { paidOff: false, pays: pays, interest: interestTotal };
  }

  function levelPayment(amount, apr, months) {
    var r = apr / 12;
    return cents(r === 0 ? amount / months : r * amount / (1 - Math.pow(1 + r, -months)));
  }

  // n payments of P; the last one is adjusted to clear the balance.
  function amortize(amount, apr, months, payment) {
    var r = apr / 12, bal = amount, interestTotal = 0, pays = [];
    for (var m = 1; m <= months; m++) {
      var interest = cents(bal * r);
      bal += interest;
      var pay = m === months ? bal : Math.min(payment, bal);
      bal -= pay; interestTotal += interest; pays.push(pay);
      if (bal <= 0.005) break;
    }
    return { pays: pays, interest: interestTotal };
  }

  function pv(payment, i, n) { return i === 0 ? payment * n : payment * (1 - Math.pow(1 + i, -n)) / i; }

  // Periodic rate at which n payments of `payment` are worth `received` today (bisection).
  function solveRate(payment, n, received) {
    if (received <= 0 || payment * n <= received) return 0;
    var lo = 0, hi = 1;
    while (pv(payment, hi, n) > received && hi < 1e6) hi *= 2;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (pv(payment, mid, n) > received) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function mca(advance, factor, termMonths, paidMonths, perYear) {
    var payback = advance * factor;
    var n = Math.max(1, Math.round(termMonths * perYear / 12));
    var debit = payback / n;
    var apr = solveRate(debit, n, advance) * perYear;
    var monthly = payback / termMonths;
    var left = termMonths - paidMonths;
    return { payback: payback, n: n, debit: debit, apr: apr, monthly: monthly, monthsLeft: left, payoff: monthly * left };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }
  function pct(x) { return (x * 100).toFixed(2) + '%'; }
  function signedMoney(x) {
    if (Math.abs(x) < 0.005) return money.format(0);
    return (x > 0 ? '+' : '−') + money.format(Math.abs(x));
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }
  function raw(id) { return document.getElementById(id).value.trim(); }
  function num(id) { var v = parseFloat(raw(id)); return isNaN(v) ? NaN : v; }
  function mark(id, bad) { document.getElementById(id).setAttribute('aria-invalid', String(bad)); }

  function readDebts() {
    var list = [], problem = '';
    for (var i = 1; i <= LOAN_ROWS; i++) {
      var ids = ['bdcBal' + i, 'bdcApr' + i, 'bdcPay' + i];
      var bal = num(ids[0]), apr = num(ids[1]), pay = num(ids[2]);
      if (raw(ids[0]) === '' || bal === 0) { ids.forEach(function (id) { mark(id, false); }); continue; }
      var bb = isNaN(bal) || bal < 0 || bal > 1e9, ba = isNaN(apr) || apr < 0 || apr > 100, bp = isNaN(pay) || pay <= 0;
      mark(ids[0], bb); mark(ids[1], ba); mark(ids[2], bp);
      var label = TYPE_NAMES[document.getElementById('bdcType' + i).value] + ' (row ' + i + ')';
      if (bb || ba || bp) { problem = problem || 'Check ' + label + ': a balance above $0, an APR from 0 to 100% and a monthly payment above $0.'; continue; }
      var s = payDown(bal, apr / 100, pay);
      if (!s.paidOff) { problem = problem || 'The payment on ' + label + ' does not cover its monthly interest of about ' + money.format(bal * apr / 1200) + ', so it never gets paid off. Raise that payment.'; continue; }
      list.push({ name: label, payoff: bal, apr: apr / 100, monthly: pay, pays: s.pays, remaining: s.pays.reduce(function (a, b) { return a + b; }, 0) });
    }
    for (var j = 1; j <= MCA_ROWS; j++) {
      var mids = ['bdcMcaAdv' + j, 'bdcMcaFactor' + j, 'bdcMcaTerm' + j, 'bdcMcaPaid' + j];
      var adv = num(mids[0]), fac = num(mids[1]), term = num(mids[2]), paid = num(mids[3]);
      if (raw(mids[0]) === '' || adv === 0) { mids.forEach(function (id) { mark(id, false); }); continue; }
      if (isNaN(paid) && raw(mids[3]) === '') paid = 0;
      var b0 = isNaN(adv) || adv < 0 || adv > 1e9, b1 = isNaN(fac) || fac < 1 || fac > 3,
          b2 = isNaN(term) || term < 1 || term > 60 || Math.round(term) !== term,
          b3 = isNaN(paid) || paid < 0 || Math.round(paid) !== paid || (!b2 && paid >= term);
      mark(mids[0], b0); mark(mids[1], b1); mark(mids[2], b2); mark(mids[3], b3);
      if (b0 || b1 || b2 || b3) { problem = problem || 'Check merchant cash advance ' + j + ': a factor rate from 1.00 to 3.00, a term of 1 to 60 whole months and fewer months paid than the term.'; continue; }
      var perYear = document.getElementById('bdcMcaFreq' + j).value === 'weekly' ? 52 : 252;
      var r = mca(adv, fac, term, paid, perYear);
      var pays = [];
      for (var k = 0; k < r.monthsLeft; k++) pays.push(r.monthly);
      list.push({ name: 'Merchant cash advance ' + j, payoff: r.payoff, apr: r.apr, monthly: r.monthly, pays: pays, remaining: r.payoff, mca: r });
    }
    return { problem: problem, debts: list };
  }

  var RESULT_IDS = ['bdcNewPay', 'bdcFreed', 'bdcDscrAfter', 'bdcTotalDiff', 'bdcLoanApr', 'bdcDebtApr'];
  function clearResults() {
    RESULT_IDS.forEach(function (id) { set(id, '–'); set(id + 'Note', ''); });
    document.getElementById('bdcVerdict').hidden = true;
    clearBody('bdcCompare'); clearBody('bdcDebtTable'); clearBody('bdcYearTable');
  }

  function update() {
    var error = document.getElementById('bdcError');
    var rate = num('bdcRate'), years = num('bdcYears'), fee = num('bdcFee'), costs = num('bdcCosts');
    var noi = num('bdcNoi'), other = num('bdcOther');
    var financed = document.getElementById('bdcFinance').checked;
    if (raw('bdcFee') === '') fee = 0;
    if (raw('bdcCosts') === '') costs = 0;
    if (raw('bdcOther') === '') other = 0;
    var input = readDebts(), problem = input.problem;
    if (!problem && !input.debts.length) problem = 'Enter at least one debt or merchant cash advance to consolidate.';
    else if (!problem && (isNaN(rate) || rate < 0 || rate > 100)) problem = 'Enter a new loan rate from 0 to 100%.';
    else if (!problem && (isNaN(years) || years < 1 || years > 30)) problem = 'Enter a new loan term from 1 to 30 years.';
    else if (!problem && (isNaN(fee) || fee < 0 || fee >= 50)) problem = 'Enter an origination fee from 0% to below 50%.';
    else if (!problem && (isNaN(costs) || costs < 0)) problem = 'Enter other loan costs of $0 or more.';
    else if (!problem && (isNaN(other) || other < 0)) problem = 'Enter other yearly debt payments of $0 or more.';
    else if (!problem && raw('bdcNoi') !== '' && (isNaN(noi) || noi < -1e10)) problem = 'Enter yearly net operating income as a number.';
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    var debts = input.debts;
    var months = Math.round(years * 12);
    var D = debts.reduce(function (s, d) { return s + d.payoff; }, 0);
    var curMonthly = debts.reduce(function (s, d) { return s + d.monthly; }, 0);
    var curRemaining = debts.reduce(function (s, d) { return s + d.remaining; }, 0);
    var curMonths = Math.max.apply(null, debts.map(function (d) { return d.pays.length; }));
    var weighted = debts.reduce(function (s, d) { return s + d.payoff * d.apr; }, 0) / D;

    var f = fee / 100, L, feeAmt, upfront;
    if (financed) { L = (D + costs) / (1 - f); feeAmt = L * f; upfront = 0; }
    else { L = D; feeAmt = D * f; upfront = feeAmt + costs; }
    var payment = levelPayment(L, rate / 100, months);
    var loan = amortize(L, rate / 100, months, payment);
    var loanPaid = loan.pays.reduce(function (a, b) { return a + b; }, 0);
    var newTotal = loanPaid + upfront;
    var loanApr = solveRate(payment, months, L - feeAmt - costs) * 12;

    set('bdcNewPay', money.format(payment));
    set('bdcNewPayNote', 'Loan of ' + money.format(L) + ' over ' + duration(months) + (financed && (feeAmt + costs) > 0 ? ', fees included.' : '.'));
    var freed = curMonthly - payment;
    set('bdcFreed', signedMoney(freed));
    set('bdcFreedNote', 'Against ' + money.format(curMonthly) + ' a month on the debts today' + (freed >= 0 ? ' — cash freed each month.' : ' — the loan costs more each month.'));

    var otherYear = other;
    var dsBefore = curMonthly * 12 + otherYear, dsAfter = payment * 12 + otherYear;
    var hasNoi = raw('bdcNoi') !== '' && !isNaN(noi);
    if (hasNoi && dsAfter > 0 && dsBefore > 0) {
      set('bdcDscrAfter', (noi / dsAfter).toFixed(2) + 'x');
      set('bdcDscrAfterNote', 'Up from ' + (noi / dsBefore).toFixed(2) + 'x today. Lenders commonly look for about 1.25x or more.');
      if (noi / dsAfter < noi / dsBefore) set('bdcDscrAfterNote', 'Down from ' + (noi / dsBefore).toFixed(2) + 'x today. Lenders commonly look for about 1.25x or more.');
    } else {
      set('bdcDscrAfter', '–');
      set('bdcDscrAfterNote', 'Enter yearly net operating income to see coverage.');
    }

    var diff = curRemaining - newTotal;
    set('bdcTotalDiff', signedMoney(-diff));
    set('bdcTotalDiffNote', diff >= 0 ? 'Less paid in total than the ' + money0.format(curRemaining) + ' left on the debts.' : 'More paid in total than the ' + money0.format(curRemaining) + ' left on the debts, mainly from the longer term.');
    set('bdcLoanApr', pct(loanApr));
    set('bdcLoanAprNote', 'The ' + rate.toFixed(2) + '% rate plus the fee and costs.');
    set('bdcDebtApr', pct(weighted));
    set('bdcDebtAprNote', 'Payoff-weighted average of the debts being replaced.');

    var verdict = document.getElementById('bdcVerdict');
    verdict.hidden = false;
    var good = freed >= 0 && diff >= 0;
    verdict.className = 'callout mt-5 ' + (good ? 'callout-success' : (freed >= 0 ? 'callout-note' : 'callout-warning'));
    set('bdcVerdictTitle', good ? 'Better cash flow and a lower total cost' : (freed >= 0 ? 'Better monthly cash flow, but a higher total cost' : 'The new loan raises your monthly payments'));
    set('bdcVerdictText', good
      ? 'Consolidating frees ' + money.format(freed) + ' a month and saves ' + money.format(diff) + ' over the life of the debts.'
      : (freed >= 0
        ? 'You keep ' + money.format(freed) + ' more cash each month, but spreading the debt over ' + duration(months) + ' costs ' + money.format(-diff) + ' more in total. That can still be worth it if the cash relief keeps the business running smoothly.'
        : 'The single payment is ' + money.format(-freed) + ' a month higher than the debts it replaces' + (diff >= 0 ? ', although it saves ' + money.format(diff) + ' in total.' : ' and costs more in total. Try a longer term or a lower rate.')));

    var cmp = clearBody('bdcCompare');
    addRow(cmp, ['Monthly payment', money.format(curMonthly), money.format(payment), signedMoney(payment - curMonthly)]);
    addRow(cmp, ['Yearly debt service (incl. other debt)', money.format(dsBefore), money.format(dsAfter), signedMoney(dsAfter - dsBefore)]);
    addRow(cmp, ['Debt service coverage (DSCR)', hasNoi && dsBefore > 0 ? (noi / dsBefore).toFixed(2) + 'x' : '–', hasNoi && dsAfter > 0 ? (noi / dsAfter).toFixed(2) + 'x' : '–', hasNoi && dsBefore > 0 && dsAfter > 0 ? ((noi / dsAfter - noi / dsBefore) >= 0 ? '+' : '−') + Math.abs(noi / dsAfter - noi / dsBefore).toFixed(2) : '–']);
    addRow(cmp, ['Time to debt-free', duration(curMonths), duration(loan.pays.length), loan.pays.length === curMonths ? 'Same' : (loan.pays.length < curMonths ? duration(curMonths - loan.pays.length) + ' sooner' : duration(loan.pays.length - curMonths) + ' later')]);
    addRow(cmp, ['Fees and costs paid up front', money.format(0), money.format(upfront), signedMoney(upfront)]);
    addRow(cmp, ['Total still to pay', money.format(curRemaining), money.format(newTotal), signedMoney(newTotal - curRemaining)]);

    var tb = clearBody('bdcDebtTable');
    debts.forEach(function (d) {
      addRow(tb, [d.name, money.format(d.payoff), money.format(d.monthly), pct(d.apr), duration(d.pays.length), money.format(d.remaining)]);
    });

    var yt = clearBody('bdcYearTable');
    var horizon = Math.max(curMonths, loan.pays.length), cum = 0;
    for (var y = 1; y <= Math.ceil(horizon / 12); y++) {
      var a = 0, b = 0;
      for (var m = (y - 1) * 12; m < y * 12; m++) {
        debts.forEach(function (d) { if (m < d.pays.length) a += d.pays[m]; });
        if (m < loan.pays.length) b += loan.pays[m];
      }
      if (y === 1) b += upfront;
      cum += a - b;
      addRow(yt, [String(y), money.format(a), money.format(b), signedMoney(a - b), signedMoney(cum)]);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('bdcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
